DROP TABLE IF EXISTS `sys_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `config_key` varchar(128) NOT NULL COMMENT '参数键,如 expense.invoice.required',
  `config_name` varchar(200) NOT NULL COMMENT '参数名称',
  `config_value` varchar(2000) DEFAULT NULL COMMENT '参数值',
  `value_type` varchar(20) NOT NULL DEFAULT 'STRING' COMMENT '值类型:STRING/NUMBER/BOOLEAN/JSON/DATE',
  `group_code` varchar(64) DEFAULT 'COMMON' COMMENT '参数分组,用于页面分栏展示',
  `is_builtin` tinyint NOT NULL DEFAULT '0' COMMENT '是否内置:1内置(不可删,只能改值)',
  `editable` tinyint NOT NULL DEFAULT '1' COMMENT '租户是否可改:0只读 1可改',
  `remark` varchar(500) DEFAULT NULL COMMENT '说明(页面上的帮助文字)',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_config_key` (`tenant_id`,`config_key`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_group` (`tenant_id`,`group_code`)
) ENGINE=InnoDB AUTO_INCREMENT=9048 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='租户参数配置';
/*!40101 SET character_set_client = @saved_cs_client */;

