INSERT INTO `sys_config` VALUES (1,1,'expense.invoice.required','报销是否附发票（登记项·本参数未被业务逻辑读取）','TRUE','BOOLEAN','COMMON',0,1,'D-F1R-24（2026-10-28）：全仓检索本键仅 SysConfig.java 注释提到，无任何消费方；实际\"报销必须有票\"由 ExpenseBillService:917 / PrecheckService:122 走费用政策(ExpensePolicy)判定。本行只作登记，不得以本参数值下判合规性。',NULL,'2026-08-11 15:52:38',1,'2026-10-28 06:57:45',0),(2,1,'expense.amount.limit','单笔报销上限(元)（登记项·本参数未被业务逻辑读取）','100000','NUMBER','COMMON',0,1,'D-F1R-24（2026-10-28）：本键全仓零消费方；实测 5,200,000 的报销单不受本值拦截（一路走完 12 节并付款）。金额档真实口径=流程模型 CLAIM 的四道金额网关（>5万/>20万/>50万/>500万）。不得以本参数值当上限。',NULL,'2026-08-11 15:52:38',1,'2026-10-28 06:57:45',0),(5,1,'notify.wecom_webhook','企业微信 webhook','','string','NOTIFY',1,1,'群机器人地址（群设置→群机器人→添加），空=不启用企微渠道',1,'2026-08-13 12:48:26',NULL,'2026-08-13 12:48:26',0),(6,1,'notify.mail.host','SMTP 服务器','','string','NOTIFY',1,1,'如 smtp.qq.com / smtp.exmail.qq.com',1,'2026-08-13 12:48:26',NULL,'2026-08-13 12:48:26',0),(7,1,'notify.mail.port','SMTP 端口','465','string','NOTIFY',1,1,'SSL 默认 465',1,'2026-08-13 12:48:26',NULL,'2026-08-13 12:48:26',0),(8,1,'notify.mail.username','SMTP 账号','','string','NOTIFY',1,1,'发件邮箱',1,'2026-08-13 12:48:26',NULL,'2026-08-13 12:48:26',0),(9,1,'notify.mail.password','SMTP 密码/授权码','','string','NOTIFY',1,1,'邮箱 SMTP 授权码',1,'2026-08-13 12:48:26',NULL,'2026-08-13 12:48:26',0),(10,1,'notify.mail.from','发件人地址','','string','NOTIFY',1,1,'一般同 SMTP 账号',1,'2026-08-13 12:48:26',NULL,'2026-08-13 12:48:26',0),(11,1,'notify.job_alert_user','定时任务告警接收用户ID','1','string','NOTIFY',1,1,'站内信告警接收人用户ID，默认演示管理员',1,'2026-08-29 09:31:39',NULL,'2026-08-29 09:31:39',0),(12,1,'archive.cold_months','冷热分离归档月数阈值','12','number','ARCHIVE',1,1,'update_time 早于当前时间 N 个月且状态为终态的单据才归档，默认 12',1,'2026-08-29 14:39:35',NULL,'2026-08-29 14:39:35',0),(13,1,'archive.terminal_status','归档终态集合','POSTED,PAID,DONE,REPAID,CLOSED','string','ARCHIVE',1,1,'允许归档的终态集合（逗号分隔），额外安全网：APPROVING/DRAFT/SUBMITTED 任何在途态一律不搬',1,'2026-08-29 14:39:35',NULL,'2026-08-29 14:39:35',0),(14,1,'archive.enabled','冷热分离归档开关','0','number'